SELECT price * quantity AS total
FROM order_items
WHERE total > 100;

-- sizes: 3 rows
-- colours: 4 rows
SELECT * FROM sizes CROSS JOIN colours;

SELECT e.name, m.name AS manager
FROM employees e
JOIN employees m ON m.id = e.manager_id;

-- a.x: 1, 2, 2
-- b.x: 2, 2, 3
SELECT * FROM a JOIN b ON a.x = b.x;

SELECT dept, name, MAX(salary)
FROM employees
GROUP BY dept;

WITH totals AS (
  SELECT customer_id, SUM(amount) AS spent
  FROM orders
  GROUP BY customer_id
)
SELECT COUNT(*) FROM totals WHERE spent > 100;

WITH RECURSIVE n(i) AS (
  SELECT 1
  UNION ALL
  SELECT i + 1 FROM n WHERE i < 5
)
SELECT SUM(i) FROM n;

SELECT name
FROM products
WHERE price = (SELECT price FROM products WHERE category = 'books');

SELECT dept, name, salary,
       AVG(salary) OVER (PARTITION BY dept) AS dept_avg
FROM employees;

-- prices(day, price): (1, 100), (2, 110), (3, 105)
SELECT day, price - LAG(price) OVER (ORDER BY day) AS change
FROM prices;

